// Real-Chrome check of the Ritanya BROWSER engine on a deployed URL (a protected Preview, or any host), or a local server.
//
//   node tests/e2e/ritanya_engine_check.js <URL> <OUT_DIR>
//
// The server must be running this branch with RITHAVO_RITANYA_MODE=browser. URL may carry ?_vercel_share=... for a protected
// Preview (the share cookie is added to every request at the network layer, as in the other preview checks).
// What it proves, in a real browser: the engine's answers equal the Python reference (fixture generated by pytest); a whole
// conversation makes ZERO network requests; the guide works offline; the kill switch removes it; failures fall back plainly.
// Exit code 0 only if every check passes.

const { spawn } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { isDeepStrictEqual } = require("node:util");

const INPUT = process.argv[2];
const OUT = process.argv[3] || path.join(os.tmpdir(), "ritanya-engine-evidence");
if (!INPUT) { console.error("usage: ritanya_engine_check.js <URL> <OUT_DIR>"); process.exit(2); }
const BASE = new URL(INPUT).origin;
const HAS_SHARE = new URL(INPUT).searchParams.has("_vercel_share");
fs.mkdirSync(OUT, { recursive: true });
const FIXTURE = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "fixtures", "ritanya_parity_sample.json"), "utf8"));
const chromePath = [process.env.CHROME_PATH, "C:/Program Files/Google/Chrome/Application/chrome.exe", "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe"].filter(Boolean).find((p) => fs.existsSync(p));
if (!chromePath) { console.error("No Chromium found"); process.exit(2); }
const results = [];
function check(name, ok, detail = "") { results.push(ok); console.log((ok ? "PASS " : "FAIL ") + name + (detail ? `  [${String(detail).slice(0, 240)}]` : "")); }
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const port = 9300 + Math.floor(Math.random() * 500);
  const chrome = spawn(chromePath, [`--remote-debugging-port=${port}`, `--user-data-dir=${fs.mkdtempSync(path.join(os.tmpdir(), "eng-chrome-"))}`, "--headless=new", "--no-first-run", "--no-default-browser-check", "--disable-gpu", "--window-size=1280,900", "about:blank"], { stdio: "ignore" });
  let bw; for (let i = 0; i < 60 && !bw; i++) { try { bw = (await (await fetch(`http://127.0.0.1:${port}/json/version`)).json()).webSocketDebuggerUrl; } catch (e) { /* not up */ } if (!bw) await sleep(250); }
  if (!bw) throw new Error("Chrome did not start");
  const ws = new WebSocket(bw); await new Promise((r) => (ws.onopen = r));
  let id = 0; const pending = new Map(); const events = []; const net = []; let cookieHeader = "", sess, mocks = [], collecting = false;
  const sendTo = (s, method, params = {}) => new Promise((res, rej) => { const i = ++id; pending.set(i, (d) => (d.error ? rej(new Error(method + ": " + d.error.message)) : res(d.result))); ws.send(JSON.stringify({ id: i, method, params, ...(s ? { sessionId: s } : {}) })); });
  ws.onmessage = (m) => {
    const d = JSON.parse(m.data);
    if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); return; }
    if (d.method === "Network.requestWillBeSent" && collecting) net.push({ url: d.params.request.url, method: d.params.request.method, type: d.params.type });
    if (d.method === "Fetch.requestPaused" && d.sessionId) {
      const { requestId, request } = d.params;
      const mock = mocks.find((x) => x.match(request.url, request.method));
      if (mock) {
        if (mock.fail) sendTo(d.sessionId, "Fetch.failRequest", { requestId, errorReason: "ConnectionRefused" }).catch(() => {});
        else sendTo(d.sessionId, "Fetch.fulfillRequest", { requestId, responseCode: mock.status, responseHeaders: [{ name: "Content-Type", value: mock.type || "application/json" }, { name: "Cache-Control", value: "no-store" }], body: Buffer.from(mock.body || "").toString("base64") }).catch(() => {});
        return;
      }
      const headers = Object.entries(request.headers).map(([name, value]) => ({ name, value }));
      if (cookieHeader && !headers.some((h) => h.name.toLowerCase() === "cookie")) headers.push({ name: "Cookie", value: cookieHeader });
      sendTo(d.sessionId, "Fetch.continueRequest", { requestId, headers }).catch(() => {});
      return;
    }
    if (d.method) events.push(d);
  };
  const { targetId } = await sendTo(null, "Target.createTarget", { url: "about:blank" });
  ({ sessionId: sess } = await sendTo(null, "Target.attachToTarget", { targetId, flatten: true }));
  const send = (m, p) => sendTo(sess, m, p);
  const workerSessions = new Map();
  async function setOffline(offline) {
    const c = { offline, latency: 0, downloadThroughput: offline ? 0 : -1, uploadThroughput: offline ? 0 : -1 };
    await send("Network.emulateNetworkConditions", c);
    const { targetInfos } = await sendTo(null, "Target.getTargets");
    for (const t of targetInfos.filter((x) => x.type === "service_worker")) {
      try { let s = workerSessions.get(t.targetId); if (!s) { ({ sessionId: s } = await sendTo(null, "Target.attachToTarget", { targetId: t.targetId, flatten: true })); workerSessions.set(t.targetId, s); await sendTo(s, "Network.enable"); } await sendTo(s, "Network.emulateNetworkConditions", c); } catch (e) { /* gone */ }
    }
  }
  const evalJs = async (e) => { const r = await send("Runtime.evaluate", { expression: e, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "eval"); return r.result.value; };
  const pageEvents = () => events.filter((e) => e.sessionId === sess);
  const goto = async (u) => { events.length = 0; await send("Page.navigate", { url: u }); for (let i = 0; i < 80; i++) { if (pageEvents().some((e) => e.method === "Page.loadEventFired")) break; await sleep(150); } await sleep(600); };
  const waitFor = async (expr, ms = 8000) => { const end = Date.now() + ms; while (Date.now() < end) { try { if (await evalJs(expr)) return true; } catch (e) { /* retry */ } await sleep(200); } return false; };
  const shot = async (n) => { const r = await send("Page.captureScreenshot", { format: "png" }); fs.writeFileSync(path.join(OUT, n + ".png"), Buffer.from(r.data, "base64")); };
  await send("Page.enable"); await send("Runtime.enable"); await send("Network.enable");
  await goto(INPUT);
  if (HAS_SHARE) { const { cookies } = await send("Network.getCookies", { urls: [BASE + "/"] }); cookieHeader = cookies.map((c) => `${c.name}=${c.value}`).join("; "); }
  await send("Fetch.enable", { patterns: [{ urlPattern: BASE + "/*" }] });
  collecting = true;

  const api = (p, init) => evalJs(`fetch(${JSON.stringify(p)}, Object.assign({credentials:'omit',cache:'no-store'}, ${JSON.stringify(init || {})})).then(async r=>({s:r.status,h:Object.fromEntries(r.headers.entries()),t:await r.text()}))`);
  const openPanel = async () => { await evalJs(`document.querySelector('.rtn-launcher').click()`); return waitFor(`!document.querySelector('.rtn-root').hidden`, 4000); };
  const resetConvo = () => evalJs(`document.querySelector('.rtn-iconbtn[aria-label="New conversation"]').click()`);
  const lastMsg = () => evalJs(`(()=>{const m=[...document.querySelectorAll('.rtn-ritanya')].pop();if(!m)return null;return{text:m.querySelector('.rtn-bubble').textContent,actions:[...m.querySelectorAll('.rtn-action')].map(a=>({label:a.textContent.replace('Sign-in required','').trim(),href:a.getAttribute('href')})),chips:[...m.querySelectorAll('.rtn-chip')].map(c=>c.textContent)}})()`);
  const ask = async (text) => {
    const n = await evalJs(`document.querySelectorAll('.rtn-ritanya').length`);
    await evalJs(`(()=>{const i=document.querySelector('.rtn-input');i.value=${JSON.stringify(text)};document.querySelector('.rtn-form').requestSubmit()})()`);
    await waitFor(`document.querySelectorAll('.rtn-ritanya').length>${n} && !document.querySelector('.rtn-send').disabled`, 10000);
    return lastMsg();
  };
  const expectedFor = (m) => { const i = FIXTURE.cases.findIndex((c) => c.m === m && !("t" in c) && !("s" in c)); return i >= 0 ? FIXTURE.expected[i] : null; };

  // ===================================================================== the server tells the page to use the engine
  await goto(BASE + "/career/");
  const st = await api("/api/ritanya/status");
  const cfg = JSON.parse(st.t || "{}");
  check("status: enabled, engine 'browser', a version fingerprint, the browser disclosure, edge-cacheable", st.s === 200 && cfg.enabled === true && cfg.engine === "browser" && /^[0-9a-f]{12}$/.test(cfg.engine_version || "") && /not sent to Rithavo or anyone else/.test(cfg.disclosure) && /max-age=60/.test(st.h["cache-control"] || ""), JSON.stringify({ e: cfg.engine, v: cfg.engine_version, cc: st.h["cache-control"], vc: st.h["x-vercel-cache"] }));
  const chat404 = await api("/api/ritanya/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message: "hi" }) });
  check("there is no chat route (404): the server cannot receive a message", chat404.s === 404, String(chat404.s));
  check("the launcher appears and the engine was requested once, as this exact version, from this origin", await waitFor(`!!document.querySelector('.rtn-launcher') && !!window.RitanyaEngine`, 8000) && (await evalJs(`[...document.scripts].some(s=>s.src===location.origin+'/assets/ritanya/engine.js?v=${cfg.engine_version}')`)));
  check("the engine exposes only its functions", JSON.stringify(Object.keys(await evalJs(`Object.fromEntries(Object.keys(window.RitanyaEngine).map(k=>[k,typeof window.RitanyaEngine[k]]))`)).sort()) === JSON.stringify(["answer", "clean", "norm", "respond", "topics", "validate"].sort()));

  // ===================================================================== real-browser parity with the Python reference
  const got = await evalJs(`(()=>{const E=window.RitanyaEngine;return ${JSON.stringify(FIXTURE.cases)}.map(c=>E.respond(c.m,'t' in c?c.t:undefined,'s' in c?c.s:undefined))})()`);
  const diffs = got.map((g, i) => (isDeepStrictEqual(g, FIXTURE.expected[i]) ? -1 : i)).filter((i) => i >= 0);
  check(`parity in Chrome: ${FIXTURE.cases.length} cases (every topic, follow-ups, hostile, unsupported, validation) equal the Python reference`, diffs.length === 0, diffs.slice(0, 3).map((i) => JSON.stringify(FIXTURE.cases[i]).slice(0, 80)).join(" | "));

  // ===================================================================== a whole conversation makes zero network requests
  await openPanel(); await resetConvo();
  const SCRIPT = FIXTURE.conversation.messages;
  net.length = 0;
  const replies = [];
  for (const q of SCRIPT) replies.push(await ask(q));
  const during = net.slice();
  console.log(`INFO ${SCRIPT.length} messages sent; network requests made while the conversation ran: ${during.length}${during.length ? " -> " + during.map((r) => r.method + " " + r.url).join(", ") : ""}`);
  check(`a ${SCRIPT.length}-message conversation made ZERO network requests (no chat call, no status call, no asset)`, during.length === 0, during.map((r) => r.url).join(" "));
  const mism = [];
  SCRIPT.forEach((q, i) => {
    const e = FIXTURE.conversation.expected[i], r = replies[i];
    if (r.text !== e.reply || JSON.stringify(r.actions.map((a) => a.href)) !== JSON.stringify(e.hrefs)) mism.push(q);
    if (i < SCRIPT.length - 1 && JSON.stringify(r.chips.filter(Boolean)) !== JSON.stringify(e.chips.slice(0, 4))) mism.push(q + " (suggestions)");
  });
  check(`every reply, link and suggestion in the panel equals the Python reference at each of the ${SCRIPT.length} steps (state carried: last topic, repeated unknown)`, mism.length === 0, mism.join(" | "));
  check("refusals and fallbacks behave as approved (personal request, off-site request, account data, unsupported)", /can't assess your resume/.test(replies[8].text) && /can't change how I work/.test(replies[9].text) && /can't see your account/.test(replies[10].text) && /I don't have information about that/.test(replies[11].text) && /hello@rithavo\.com/.test(replies[12].text));
  check("prices stay disabled and availability is never asserted", !/[\u20b9]|\b\d{3}\b/.test(replies[3].text) && /can't see what is open today/.test(replies[4].text) && !/available now|live now/i.test(replies.map((r) => r.text).join(" ")));
  check("the Card answer says it isn't available on rithavo.com and links nowhere near a card site", /isn't available on rithavo\.com/.test(replies[7].text) && replies[7].actions.every((a) => a.href.startsWith("/") && !/card/i.test(a.href)));
  check("every link offered is a relative path on this site", replies.every((r) => r.actions.every((a) => /^\/[^\/\\\s]/.test(a.href) || a.href === "/")));
  await shot("engine-conversation");

  // ===================================================================== markup typed by the visitor
  await evalJs(`window.__xss = 0`);
  await ask(`<img src=x onerror="window.__xss=1"><script>window.__xss=2</script> "><svg onload=window.__xss=3>`);
  await sleep(300);
  check("hostile markup typed by the visitor is shown as text and never executes", (await evalJs(`window.__xss`)) === 0 && (await evalJs(`document.querySelectorAll('.rtn-log img, .rtn-log script, .rtn-log svg[onload]').length`)) === 0);

  // ===================================================================== storage and cookies
  const storage = await evalJs(`({session:Object.keys(sessionStorage),local:Object.keys(localStorage),cookie:document.cookie})`);
  check("only the tab's own rv_ritanya_* keys are stored; no localStorage; the guide set no cookie", storage.session.every((k) => k.startsWith("rv_ritanya_")) && storage.local.length === 0 && !/ritanya/i.test(storage.cookie), JSON.stringify({ s: storage.session, l: storage.local }));

  // ===================================================================== offline: a fresh page load still answers (engine and shell come from the service-worker cache)
  await goto(BASE + "/about/"); await waitFor(`!!window.RitanyaEngine`, 6000);
  await goto(BASE + "/career/"); await waitFor(`!!window.RitanyaEngine`, 6000);
  const cachedEngine = await evalJs(`caches.keys().then(async ks=>{for(const k of ks){const c=await caches.open(k);for(const r of await c.keys()){if(/ritanya\\/engine\\.js/.test(r.url))return k}}return null})`);
  check("the service worker has cached the engine file (a public asset)", !!cachedEngine, String(cachedEngine));
  await setOffline(true);
  await goto(BASE + "/about/");
  check("offline: a page loaded from cache still shows the guide with its engine", await waitFor(`!!document.querySelector('.rtn-launcher') && !!window.RitanyaEngine`, 8000));
  await openPanel(); await resetConvo();
  const off = await ask("What is Career Intelligence?");
  check("offline: the guide still answers (nothing needed the network)", /four kinds of move|Stay, New Role/.test(off.text), off.text.slice(0, 70));
  await setOffline(false); await sleep(600);

  // ===================================================================== kill switch (the server's answer is simulated here; the server side is covered by tests and the paused Preview)
  await goto(BASE + "/career/"); await waitFor(`!!document.querySelector('.rtn-launcher')`, 6000); await openPanel();
  await ask("What is Rithavo?");
  const before = await evalJs(`!!sessionStorage.getItem('rv_ritanya_conversation')`);
  await evalJs(`(()=>{const v=JSON.parse(sessionStorage.getItem('rv_ritanya_status'));v.t=Date.now()-600000;sessionStorage.setItem('rv_ritanya_status',JSON.stringify(v))})()`);   // the "on" answer is now old
  mocks = [{ match: (u) => /\/api\/ritanya\/status/.test(u), status: 200, body: JSON.stringify({ enabled: false }) }];
  const askedBefore = net.filter((r) => /ritanya\/status/.test(r.url)).length;
  await ask("What is Career Intelligence?");
  await sleep(700);
  const gone = await evalJs(`({launcher:!!document.querySelector('.rtn-launcher'),root:!!document.querySelector('.rtn-root'),spacer:!!document.querySelector('.rtn-spacer'),conv:sessionStorage.getItem('rv_ritanya_conversation'),on:document.body.classList.contains('rtn-on')})`);
  check("kill switch: when the server says off, the next message re-asks the server and the whole guide disappears", net.filter((r) => /ritanya\/status/.test(r.url)).length > askedBefore && !gone.launcher && !gone.root && !gone.spacer && !gone.on, JSON.stringify(gone));
  check("kill switch: what the visitor typed is cleared when the guide is switched off", before === true && gone.conv === null);
  await goto(BASE + "/systems/"); await sleep(1500);
  check("kill switch: a new page while the server still says off shows no guide", !(await evalJs(`!!document.querySelector('.rtn-launcher')`)));
  mocks = [{ match: (u) => /\/api\/ritanya\/status/.test(u), status: 500, body: "boom", type: "text/plain" }];
  await evalJs(`sessionStorage.removeItem('rv_ritanya_status')`);
  await goto(BASE + "/growth/"); await sleep(1500);
  check("a server error on the status call does not switch the guide on", !(await evalJs(`!!document.querySelector('.rtn-launcher')`)));
  mocks = [];
  await evalJs(`sessionStorage.removeItem('rv_ritanya_status')`);
  await goto(BASE + "/growth/");
  check("and when the server says on again, the guide comes back", await waitFor(`!!document.querySelector('.rtn-launcher')`, 8000));
  // a transient failure while open must NOT remove a working guide
  await openPanel(); await ask("What is Rithavo?");
  await evalJs(`(()=>{const v=JSON.parse(sessionStorage.getItem('rv_ritanya_status'));v.t=Date.now()-180000;sessionStorage.setItem('rv_ritanya_status',JSON.stringify(v))})()`);   // stale (3 min) but inside the 5-minute grace period
  mocks = [{ match: (u) => /\/api\/ritanya\/status/.test(u), fail: true }];
  const still = await ask("What is Career Intelligence?");
  mocks = [];
  check("a brief interruption (inside the grace period) keeps a working guide working; the full outage matrix is in ritanya_killswitch_check.js", /four kinds|Stay, New Role/.test(still.text) && (await evalJs(`!!document.querySelector('.rtn-launcher, .rtn-root')`)));

  // ===================================================================== engine file fails to load
  mocks = [{ match: (u) => /\/assets\/ritanya\/engine\.js/.test(u), status: 500, body: "nope", type: "text/plain" }];
  await send("Network.setBypassServiceWorker", { bypass: true });      // the worker would (correctly) serve the cached engine; this step tests the network failing
  await evalJs(`sessionStorage.clear()`);
  await goto(BASE + "/contact/");
  await sleep(2500);
  const failed = await evalJs(`({launcher:!!document.querySelector('.rtn-launcher'),root:!!document.querySelector('.rtn-root'),spacer:!!document.querySelector('.rtn-spacer'),on:document.body.classList.contains('rtn-on'),nav:document.querySelectorAll('nav a[href]').length})`);
  mocks = [];
  await send("Network.setBypassServiceWorker", { bypass: false });
  check("if the engine file cannot load, no guide is mounted at all (no launcher, no half-working panel); the page's own navigation is untouched", !failed.launcher && !failed.root && !failed.spacer && !failed.on && failed.nav > 0, JSON.stringify(failed));

  // ===================================================================== installed app on a phone, accessibility
  await evalJs(`sessionStorage.clear()`);
  await send("Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  const shim = await send("Page.addScriptToEvaluateOnNewDocument", { source: "Object.defineProperty(navigator,'standalone',{get:()=>true})" });
  await goto(BASE + "/systems/"); await waitFor(`!!document.querySelector('.rtn-launcher') && !!document.querySelector('.pwa-bottomnav') && !!window.RitanyaEngine`, 10000);
  const lay = await evalJs(`(()=>{const l=document.querySelector('.rtn-launcher').getBoundingClientRect(),n=document.querySelector('.pwa-bottomnav').getBoundingClientRect();return{ok:l.bottom<=n.top,overflowX:document.documentElement.scrollWidth>innerWidth}})()`);
  check("installed app on a phone: the launcher sits above the bottom navigation, no sideways scroll", lay.ok && !lay.overflowX, JSON.stringify(lay));
  await openPanel(); await resetConvo();
  const prof = await ask("What is a Rithavo Profile?");
  check("installed app: answers match the browser's (same engine, no Card special case)", /Profile/.test(prof.text) && prof.chips.length >= 1, JSON.stringify(prof.chips));
  await shot("engine-installed-mobile");
  await send("Page.removeScriptToEvaluateOnNewDocument", { identifier: shim.identifier });
  await send("Emulation.clearDeviceMetricsOverride");
  await goto(BASE + "/about/"); await waitFor(`!!document.querySelector('.rtn-launcher')`, 8000); await openPanel(); await sleep(200);
  const a11y = await evalJs(`({role:document.querySelector('.rtn-panel').getAttribute('role'),focus:document.activeElement.className})`);
  await send("Input.dispatchKeyEvent", { type: "keyDown", key: "Escape", code: "Escape", windowsVirtualKeyCode: 27 }); await send("Input.dispatchKeyEvent", { type: "keyUp", key: "Escape", code: "Escape", windowsVirtualKeyCode: 27 }); await sleep(300);
  const closed = await evalJs(`({hidden:document.querySelector('.rtn-root').hidden,focus:document.activeElement.className})`);
  check("dialog is labelled, focus goes to the message box, Escape closes it and returns focus to the launcher", a11y.role === "dialog" && /rtn-input/.test(a11y.focus) && closed.hidden && /rtn-launcher/.test(closed.focus));

  // ===================================================================== what the whole session contacted
  const hosts = new Set(net.map((r) => { try { return new URL(r.url).host; } catch (e) { return ""; } }).filter(Boolean));
  const outside = [...hosts].filter((h) => h !== new URL(BASE).host && !/^fonts\.(googleapis|gstatic)\.com$/.test(h));
  check("the browser contacted only this site and the fonts it already uses", outside.length === 0, outside.join(","));

  ws.close(); chrome.kill();
  const failedN = results.filter((r) => !r).length;
  console.log(`\n${failedN === 0 ? "ALL PASS" : "FAILURES: " + failedN} (${results.length - failedN}/${results.length})  target: ${BASE}  screenshots: ${OUT}`);
  process.exit(failedN === 0 ? 0 : 1);
}
main().catch((e) => { console.error("ERROR", e); process.exit(2); });
